import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.CpLciM8b.js";const p=JSON.parse('{"title":"Cost of flakiness","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cost.md","filePath":"guide/cost.md","lastUpdated":1785918684000}'),s={name:"guide/cost.md"};function n(i,e,d,h,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="cost-of-flakiness" tabindex="-1">Cost of flakiness <a class="header-anchor" href="#cost-of-flakiness" aria-label="Permalink to &quot;Cost of flakiness&quot;">​</a></h1><p>Every other page answers <em>how flaky?</em> This one answers <em>what is it costing us?</em> — which is the question that gets flaky-test work onto a roadmap.</p><p>Open it at <strong>Cost</strong> in the project nav.</p><h2 id="what-is-measured-and-what-is-assumed" tabindex="-1">What is measured and what is assumed <a class="header-anchor" href="#what-is-measured-and-what-is-assumed" aria-label="Permalink to &quot;What is measured and what is assumed&quot;">​</a></h2><p>The distinction matters, because a number nobody can defend is worse than no number.</p><p><strong>Measured.</strong> An attempt after the first exists only because an earlier one failed. Its wall-clock is CI time a reliable suite would not have spent, and Flakemetry records it per test per day as runs arrive. Nothing is modelled or extrapolated.</p><p><strong>Assumed.</strong> Turning that time into money needs rates, and how long a red build costs somebody is not observable from test data. Three settings supply it, all under <strong>Settings → Policy</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it is</th></tr></thead><tbody><tr><td>CI cost per minute</td><td><code>0.008</code></td><td>GitHub&#39;s published rate for a 2-core Linux runner</td></tr><tr><td>Developer cost per hour</td><td><code>75</code></td><td>Fully-loaded hourly cost</td></tr><tr><td>Minutes lost per interruption</td><td><code>15</code></td><td>How long someone loses to a red build that meant nothing</td></tr></tbody></table><p>The panel prints the rates it used, and where each came from — default, dashboard, or environment variable. Set them before quoting the figure to anyone; the defaults describe a generic project, not yours.</p><p>Set the hourly cost to <code>0</code> to report CI spend only.</p><h2 id="the-two-halves" tabindex="-1">The two halves <a class="header-anchor" href="#the-two-halves" aria-label="Permalink to &quot;The two halves&quot;">​</a></h2><ul><li><strong>CI time re-running</strong> — measured wall-clock, priced per minute.</li><li><strong>Interruptions</strong> — a flaky occurrence is a test that needed a retry to pass, which is the moment somebody looks at a failure that turns out to mean nothing. Priced at the assumed minutes times the hourly rate.</li></ul><h2 id="cost-avoided-by-quarantine" tabindex="-1">Cost avoided by quarantine <a class="header-anchor" href="#cost-avoided-by-quarantine" aria-label="Permalink to &quot;Cost avoided by quarantine&quot;">​</a></h2><p>Only the interruption is credited back.</p><p>A quarantined test still runs, so its CI minutes are not saved — nothing about quarantine makes a suite cheaper to execute. What it removes is the interruption: the test no longer fails anybody&#39;s build. Counting the CI time as saved would inflate the figure and it would not survive the first person who asked how it was worked out.</p><h2 id="if-the-page-is-empty" tabindex="-1">If the page is empty <a class="header-anchor" href="#if-the-page-is-empty" aria-label="Permalink to &quot;If the page is empty&quot;">​</a></h2><p>It fills in once a test is retried. A runner with retries disabled produces no rerun wall-clock to measure, so there is genuinely nothing to attribute — see <a href="/flakemetry/v/2026-09-30/guide/reporters">Reporters</a> for enabling retries in each framework.</p><h2 id="rates-per-project" tabindex="-1">Rates per project <a class="header-anchor" href="#rates-per-project" aria-label="Permalink to &quot;Rates per project&quot;">​</a></h2><p>Rates live on the project, not the instance, because one instance can hold several projects and a browser suite on large runners does not cost what a unit suite costs. The environment variables in <a href="/flakemetry/v/2026-09-30/reference/configuration">Configuration</a> override every project at once, for when a whole instance shares one runner fleet.</p>',19)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
